  ctx.save();ctx.globalCompositeOperation='lighter';ctx.globalAlpha=a*.14;ctx.lineWidth=bw*1.3;ctx.beginPath();ctx.arc(0,0,r,0,6.283);ctx.stroke();ctx.restore();
