function lvCfg(){const L=ENV.LV;return L>=10?{rad:.338,as:.27,dur:'21',ai:1.3}:L>=5?{rad:.275,as:.22,dur:'16.5',ai:1.1}:{rad:.175,as:.14,dur:'12',ai:.9}}
