function mkFoes(){return [[120,-18,'gob'],[180,24,'wolf'],[250,-30,'gob'],[150,36,'gob'],[215,-4,'wolf'],[290,22,'gob']].map(([dx,dg,k])=>({k,x:HX+dx,y:HY+dg*K,f:-1,dx,dg,kv:0}))}
