  const g=ctx.createLinearGradient(108,0,150,-60);g.addColorStop(0,'#dfe8ff');g.addColorStop(1,'#8fa6d8');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(104,-9);ctx.quadraticCurveTo(160,-24,150,-74);ctx.quadraticCurveTo(122,-34,104,8);ctx.closePath();ctx.fill();ctx.strokeStyle='#4a5a88';ctx.lineWidth=1.5;ctx.stroke();
