// =========================================================
// Scream (เสียงหวีดวิญญาณ / Wail) - scythe buff-type 3. Balance: Lv1 fear 1.6 s, slow -21% for 4 s, r260; Lv5 fear 2.2 s slow -33% r312; Lv10 fear 2.8 s slow -40.5% r312. MP 22/27/34, CD 28.
// Hero inhales (motes gather), screams: soundwave rings expand over the area; monsters hit by the wave flinch, flee in fear (! icon), then walk slowly with a violet slow ring.
// =========================================================

const VIO='#8a4dff',VL2='#c9a8ff',DK='#3a1470',PK='#ff9fc0';
const DUST2=mk(64,64,g=>{const r=g.createRadialGradient(32,32,0,32,32,32);r.addColorStop(0,'rgba(200,190,230,.9)');r.addColorStop(.6,'rgba(170,150,210,.4)');r.addColorStop(1,'rgba(160,140,200,0)');g.fillStyle=r;g.fillRect(0,0,64,64)});
function lvCfg(){const L=ENV.LV;return L>=10?{R:312,fear:2.8,slow:'40.5%',sv:.405,ai:1.25}:L>=5?{R:312,fear:2.2,slow:'33%',sv:.33,ai:1.1}:{R:260,fear:1.6,slow:'21%',sv:.21,ai:.9}}
