let nums2=[],marks=[];
function mkFoes(){const R=lvCfg().R;const a=[[110,-18,'gob'],[170,24,'wolf'],[230,-34,'gob'],[150,40,'gob'],[260,-4,'wolf'],[330,30,'gob'],[R*.95,-30,'gob'],[R+90,10,'gob']];
  return a.map(([dx,dg,k],i)=>({k,x:HX+dx,y:HY+dg*K,f:-1,dx,dg,kv:0,lift:0,i,hit:-1,dist:Math.hypot(dx,dg),dw:Math.hypot(dx,dg)}))}
function invEase(y){let lo=0,hi=1;for(let i=0;i<24;i++){const m=(lo+hi)/2;if(ease(m)<y)lo=m;else hi=m}return hi}
